window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"uPiBG0xlPGU","speaker":"Guy Parmelin","role":"President","country":"Switzerland","region":"Europe","url":"https://www.youtube.com/watch?v=uPiBG0xlPGU","date":"20260922","title":"🇨🇭 Switzerland - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":768,"words":1631,"counts":{"claims":19,"promises":1,"attacks":0},"topics":[{"topic":"Artificial intelligence","share":0.1693,"seconds":130},{"topic":"multilateralism","share":0.1031,"seconds":79},{"topic":"International order","share":0.1001,"seconds":77},{"topic":"Switzerland trade","share":0.0851,"seconds":65},{"topic":"Switzerland UN","share":0.0841,"seconds":65},{"topic":"Switzerland diplomacy","share":0.0834,"seconds":64},{"topic":"Switzerland neutrality","share":0.0824,"seconds":63},{"topic":"UN reform","share":0.0803,"seconds":62},{"topic":"Switzerland unity","share":0.0797,"seconds":61},{"topic":"Global economy","share":0.079,"seconds":61},{"topic":"Ceremony","share":0.0535,"seconds":41}],"timeline":[[9,70,"Switzerland unity"],[71,148,"International order"],[149,210,"Global economy"],[213,278,"Switzerland trade"],[279,343,"Switzerland neutrality"],[344,408,"Switzerland diplomacy"],[409,474,"Switzerland UN"],[476,544,"Artificial intelligence"],[548,610,"Artificial intelligence"],[611,673,"UN reform"],[673,752,"multilateralism"],[753,794,"Ceremony"]],"stances":{"Switzerland unity":"Guy Parmelin describes Switzerland's history of learning to live with internal divisions by building infrastructure to connect them.","International order":"Guy Parmelin states that the post-World War II international order is under severe constraints due to multiplying conflicts and violations of UN Charter principles.","Global economy":"Guy Parmelin states that trust erosion extends to the global economy, citing rising protectionism and fragmented supply chains due to geopolitical tensions.","Switzerland trade":"Guy Parmelin argues that Switzerland's prosperity depends on international trade governed by common rules rather than state power.","Switzerland neutrality":"Guy Parmelin states that Swiss neutrality is compatible with a commitment to the UN charter and international law, and argues that dialogue is essential for maintaining contact even when positions diverge.","Switzerland diplomacy":"Guy Parmelin states that Switzerland will continue to offer its good offices and provide spaces for dialogue to de-escalate tensions and prevent crises.","Switzerland UN":"Guy Parmelin states that Switzerland will continue hosting the UN in Geneva to ensure inclusivity and emphasizes that cooperation should be based on partnership rather than imposing values.","Artificial intelligence":"Guy Parmelin argues that technological progress must broaden opportunities without widening gaps and emphasizes the need for inclusive participation in setting rules for AI development.","UN reform":"Guy Parmelin argues that UN reforms should prioritize coherence, effectiveness, and results while respecting member states' powers, focusing efforts where the UN adds value beyond national capacities.","multilateralism":"Guy Parmelin argues that while diverging interests and disagreements cannot be erased, nations can choose to preserve open dialogue, keep communication channels open, ensure technology creates opportunities rather than divisions, and reform institutions instead of accepting their demise.","Ceremony":"Guy Parmelin emphasizes the importance of dialogue and trust to overcome differences and move forward together, concluding with formal thanks."},"claims":[{"t":48,"quote":"Switzerland is a country of mountains, valleys, and different languages. Part of our history, therefore, meant learning to live with what divides us.","topic":"Switzerland unity","kind":"fact"},{"t":60,"quote":"We didn't make the mountains disappear. First, we learned to climb them, then to cross them. To do so, we built roads, bridges, and tunnels.","topic":"Switzerland unity","kind":"fact"},{"t":91,"quote":"The international order established in the aftermath of the Second World War is under severe constraints.","topic":"International order","kind":"fact"},{"t":98,"quote":"Conflicts are multiplying and becoming deadlocked.","topic":"International order","kind":"fact"},{"t":101,"quote":"The most fundamental principles of the United Nations Charter, the prohibition of the use of force and respect for sovereignty and territorial integrity are being openly violated.","topic":"International order","kind":"fact"},{"t":183,"quote":"Protectionism is on the rise. Supply chains built up over decades of are being reorganized or fragmented as a result of geopolitical tensions.","topic":"Global economy","kind":"fact"},{"t":196,"quote":"The multilateral trading system has been and the WTO can no longer fully carry out some of its essential functions.","topic":"Global economy","kind":"fact"},{"t":230,"quote":"my country is an open economy with few natural resources","topic":"Switzerland trade","kind":"fact"},{"t":235,"quote":"A large part of its prosperity therefore depends on trade, but also on the stability and predictability of the rules that make such trade possible","topic":"Switzerland trade","kind":"fact"},{"t":311,"quote":"Switzerland is neutral. This neutrality goes handinhand with a steadfast commitment to the UN charter, international law, and the UN's three pillars, peace and security, human rights, and sustainable development.","topic":"Switzerland neutrality","kind":"fact"},{"t":417,"quote":"Switzerland will therefore continue as the host state to ensure that Geneva remains open, accessible, and inclusive for large states and small for the north and the south.","topic":"Switzerland UN","kind":"fact"},{"t":485,"quote":"It offers considerable new possibilities in science, the economy, medicine, education, and the management of resources.","topic":"Artificial intelligence","kind":"fact"},{"t":534,"quote":"This is exactly the aim of the Geneva AI summit which will take place on the 21st and 22nd of June 2027 under the motto bridging innovation and trust.","topic":"Artificial intelligence","kind":"fact"},{"t":552,"quote":"Innovation in which societies no longer have confidence risks being rejected. Conversely, rules that would prevent all innovation would deprive us of enormous","topic":"Artificial intelligence","kind":"fact"},{"t":582,"quote":"Certain changes are so far reaching and so fast moving that no single state can manage all of their consequences by itself.","topic":"Artificial intelligence","kind":"fact"},{"t":611,"quote":"This reform must make the UN more coherent, more effective, and more resultsoriented while respecting the powers and responsibilities of member states.","topic":"UN reform","kind":"fact"},{"t":622,"quote":"The UN must focus its efforts where its action brings real added value when problems transcend borders when national or regional capacities are insufficient or when a universal institution is needed to provide a common framework.","topic":"UN reform","kind":"fact"},{"t":686,"quote":"We cannot make the diverging interests of our countries disappear. We cannot erase disagreements, rivalries, or borders. Nor can we remove all of the mountains that stand between us.","topic":"multilateralism","kind":"fact"},{"t":725,"quote":"Switzerland will continue to play its part using the means at its disposal by upholding international law, promoting dialogue, providing its good offices, supporting effective multilateral and by remaining a country where the world can continue to come together","topic":"multilateralism","kind":"self_credit"}],"promises":[{"t":369,"quote":"In this spirit that Switzerland will continue to offer its good offices and provide spaces where those who are no longer on speaking terms can when when circumstances permit resume","topic":"Switzerland diplomacy","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":9,"topic":"Switzerland unity","text":"The assembly will now hear an address by His Excellency President of the Swiss Confederation. I request protocol to escort his excellency and invite him to address the &gt;&gt; President of the General Assembly, United Nations Secretary General, Heads of State and Government, Your Excellencies, Ladies and Gentlemen. Switzerland is a country of mountains, valleys, and different languages. Part of our history, therefore, meant learning to live with what divides us. We didn't make the mountains disappear. First, we learned to climb them, then to cross them. To do so, we built roads, bridges, and tunnels."},{"t":71,"topic":"International order","text":"And we realized that a natural boundary is not necessarily a dividing line. It can also be a pathway that connects us. This very simple experience seems to me to have something to teach us about the world in which we live because we are going through a time of upheaval. The international order established in the aftermath of the Second World War is under severe constraints. Conflicts are multiplying and becoming deadlocked. The most fundamental principles of the United Nations Charter, the prohibition of the use of force and respect for sovereignty and territorial integrity are being openly violated. Added to this are transformations that are reshaping our societies. climate change and the increase in the number of disasters, humanitarian crises, and also technological upheavalss, notably artificial intelligence, which are often advancing faster than our collective ability to assess their At the same time, multilateral institutions are having to respond to an increasing number of crises while facing pre pressure on resources and an erosion of trust."},{"t":149,"topic":"Global economy","text":"The theme of this 81st session of the General Assembly, restoring trust, managing transformation, a united nations that delivers for all, therefore aptly sums up the task before us to restore trust. To support transformation and to demonstrate through concrete results that cooperation remains possible. This erosion of trust extends far beyond the realms of peace and security. We're also seeing it in the global economy. Protectionism is on the rise. Supply chains built up over decades of are being reorganized or fragmented as a result of geopolitical tensions. The multilateral trading system has been and the WTO can no longer fully carry out some of its essential functions. Yet what is at stake here is not merely a technical issue of trade policy."},{"t":213,"topic":"Switzerland trade","text":"The question is whether relations between states will continue to be governed by common rules or if they will increasingly depend on the weight and power of each individual state. For Switzerland, this is a fundamental issue. That is because my country is an open economy with few natural resources. A large part of its prosperity therefore depends on trade, but also on the stability and predictability of the rules that make such trade possible. Economic resilience requires us to diversify relationships, forge new partnerships, and keep trade between different regions of the world as open as possible. This is particularly important for economies with fewer resources or limited market access. Access to markets, knowledge, and technology can create opportunities that would not otherwise exist. These abstract concepts encompass quite concrete realities."},{"t":279,"topic":"Switzerland neutrality","text":"A business that can take on an apprentice, a family that can secure a more stable income, a producer who can trade beyond their local market, young people for whom the range of possibilities suddenly widens. That is also what we mean when we talk about a global economy. Trust is built when the rules offer everyone a genuine opportunity to participate. It is also built when states continue to engage in dialogue. Switzerland is neutral. This neutrality goes handinhand with a steadfast commitment to the UN charter, international law, and the UN's three pillars, peace and security, human rights, and sustainable development. Our experience has also taught us that dialogue is not a sign of weakness. Engaging in dialogue does not mean glossing over disagreements or abandoning one's principles. Engaging in dialogue means maintaining contact when positions begin to diverge."},{"t":344,"topic":"Switzerland diplomacy","text":"A bridge does not require the two banks of a river to become alike. It simply allows us to cross from one to the other. In times of tension, this possibility often becomes essential. Dialogue is a tool for deescalation. when crises erupt. Above all, it can serve as a means of prevention before crisis arise. It is in this spirit that Switzerland will continue to offer its good offices and provide spaces where those who are no longer on speaking terms can when when circumstances permit resume Geneva is one sh such space. It is home to the UN, the WTO, and numerous other international organizations, as well as scientific ones, humanitarian actors, representatives of civil society, and permanent missions of almost every country in the world. Every day, people from different backgrounds, representing interests that are sometimes at odds with one another, come together here."},{"t":409,"topic":"Switzerland UN","text":"They do not need to agree in order to talk to one another. That is exactly what gives such a place its value. Switzerland will therefore continue as the host state to ensure that Geneva remains open, accessible, and inclusive for large states and small for the north and the south. But inclusion is not merely about having a seat at the table. It also means being able to make a real contribution to decisions that will affect one's own future. This is the case with international Every society must be able to shape its future in accordance with its history, needs, and priorities. Cooperation is not about imposing one's own values or a single model. It is valuable when it creates partnerships, facilitates the sharing of expertise, and strengthens everyone's capacity to act independently. It is less about doing things for others than doing things with them."},{"t":476,"topic":"Artificial intelligence","text":"This principle takes on particular significance in the face of current technological revolutions. AI is the most obvious illustration of this. It offers considerable new possibilities in science, the economy, medicine, education, and the management of resources. But it also highlights the risk of a new divide between those who have the skills and infrastructure needed to participate in this transformation and those who are likely to feel only its effects. We must ensure that technological progress broadens opportunities without widening the gaps. This means that as many countries and societies as possible must be able to benefit from advances in develop their skills and contribute to the debate on the rules that will govern its development and use. This is exactly the aim of the Geneva AI summit which will take place on the 21st and 22nd of June 2027 under the motto bridging innovation and trust."},{"t":548,"topic":"Artificial intelligence","text":"These two concepts must go hand in hand. Innovation in which societies no longer have confidence risks being rejected. Conversely, rules that would prevent all innovation would deprive us of enormous Our responsibility therefore is to strike a balance to enable progress and promote its benefits while creating the conditions for the reliable and responsible development and use of these Artificial intelligence thus reminds us of a simple truth. Certain changes are so far reaching and so fast moving that no single state can manage all of their consequences by itself. We need institutions capable of dealing with issues that transcend national borders. We need multilateralism. But multilateralism will only retain its credibility if it is also able to evolve. Switzerland therefore supports efforts to reform the UN system as part of the UN80 initiative."},{"t":611,"topic":"UN reform","text":"This reform must make the UN more coherent, more effective, and more resultsoriented while respecting the powers and responsibilities of member states. The UN must focus its efforts where its action brings real added value when problems transcend borders when national or regional capacities are insufficient or when a universal institution is needed to provide a common framework. The key question is therefore a simple one. How can we ensure that the resources, expertise, and energy invested in the multilateral system yield better results for those it is meant to serve. Because our institutions do not exist for their own sake. They exist for the people, for those who live in fear of conflict, for those who have lost their home following a disaster, for those seeking work or building a future for themselves, for the children whose lives depend on access to education."},{"t":673,"topic":"multilateralism","text":"and the new opportunities we are creating today. It is on this scale that the value of multilateralism is ultimately measured. Ladies and gentlemen, your excellencies, we cannot make the diverging interests of our countries disappear. We cannot erase disagreements, rivalries, or borders. Nor can we remove all of the mountains that stand between us. But we can determine how we wish to tackle We can preserve open dialogue rather than erect more barriers. We can keep the channels of communication open rather than resigning ourselves to silence. We can ensure that technological progress creates more opportunities rather than new divisions. And we can reform our institutions rather than accept their gradual demise. Switzerland will continue to play its part using the means at its disposal by upholding international law, promoting dialogue, providing its good offices, supporting effective multilateral and by remaining a country where the world can continue to come together and We do not claim to have all the answers, but our experience in the Alps has taught us one simple thing."},{"t":753,"topic":"Ceremony","text":"While a mountain might separate us, it can just as easily be crossed. Crossing it brings people together. Coming together encourages dialogue, and dialogue fosters trust. Perhaps this is where our shared responsibility begins to keep open the pathways that allow us in spite of our differences to continue moving forward hand in hand. Thank you very much for your attention. On behalf of the assembly, I wish to thank the president of the Swiss"}],"compare":[{"topic":"International Law & Order","share":0.2147,"mean":0.0596,"rank":10,"others":102},{"topic":"Artificial Intelligence","share":0.1789,"mean":0.0498,"rank":12,"others":83},{"topic":"Switzerland","share":0.0881,"mean":0.0,"rank":1,"others":0},{"topic":"UN & its reform","share":0.0849,"mean":0.2054,"rank":152,"others":170},{"topic":"Global Economy","share":0.0834,"mean":0.0142,"rank":11,"others":31}]};
